#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char tok[256];
    if (scanf("%255s", tok) != 1 || tok[0] != '*') return 1;
    int so_phan_tu = atoi(tok + 1);
    for (int i = 0; i < so_phan_tu; i++) {
        char do_dai[64], noi_dung[256];
        if (scanf("%63s", do_dai) != 1) return 1;   /* dòng $độ_dài: bỏ qua */
        if (scanf("%255s", noi_dung) != 1) return 1;
        printf("%s", noi_dung);
        if (i + 1 < so_phan_tu) printf(" ");
    }
    printf("\n");
    return 0;
}
